# Lesson 6 of MKTG90037: the value proposition (Week 2, last part). Brands: Who Gives a Crap (reading of its proposition from
# its own claims), Hilton Honors, Coles. Instruments: sentence builder (Place), the critic (Tag).
from mk import *  # noqa: F403


def L06(CID):
    SK = 'mk.proposition'
    zones = [dict(id='for', label=T('For (the customer segment)', 'For（目标顾客）')), dict(id='need', label=T('who need (the problem)', 'who need（要解决的问题）')),
             dict(id='biz', label=T('our business (what we offer, in a known category)', 'our business（我们提供什么，放进一个大家懂的类别）')), dict(id='prov', label=T('that provides (the benefit)', 'that provides（带来的利益）')),
             dict(id='unl', label=T('unlike (the alternatives)', 'unlike（对比谁）')), dict(id='off', label=T('this offering (the one difference)', 'this offering（唯一的区别点）'))]
    chips = [
        dict(id='b1', label=T('households that want everyday purchases to reflect their values', '希望日常购买体现自己价值观的家庭'), zone='for', why=T('The customer segment, not the product.', '是目标顾客，不是产品。')),
        dict(id='b2', label=T('a toilet paper that does good without extra effort', '一种不用额外费劲就能做好事的卷纸'), zone='need', why=T('The need, said from the customer’s side.', '站在顾客一边说出的需求。')),
        dict(id='b3', label=T('sells recycled and bamboo toilet paper, wrapped in paper and delivered direct', '卖再生纸和竹子卷纸，纸包装，直接送货'), zone='biz', why=T('What is on offer, in a category everyone knows.', '提供什么，放进人人都懂的类别。')),
        dict(id='b4', label=T('a purchase that funds water and sanitation projects (50% of profits)', '一次购买就资助供水和卫生项目（50% 利润）'), zone='prov', why=T('The benefit, and it is quantified: the most compelling reason to buy.', '利益点，并且量化了：最有说服力的购买理由。')),
        dict(id='b5', label=T('supermarket and branded toilet paper', '超市卖的和品牌卷纸'), zone='unl', why=T('The alternatives the customer would otherwise use.', '顾客本来会用的替代品。')),
        dict(id='b6', label=T('the giving is built into the product and certified (B Corp)', '捐赠是产品的一部分，并且经过认证（B Corp）'), zone='off', why=T('The single thing that sets it apart, and the one hardest to copy.', '唯一的区别点，也最难被复制。')),
    ]
    cats = [dict(id='cust', label=T('Not from the customer’s view', '不是顾客视角')), dict(id='clear', label=T('Hard to understand', '不好懂')), dict(id='honest', label=T('Not honest', '不诚实')),
            dict(id='fit', label=T('Does not fit the business', '和业务不匹配')), dict(id='cult', label=T('Clashes with the culture', '和文化冲突'))]
    items = [
        dict(text=T('“We are the leading provider of best-in-class, end-to-end synergistic solutions.” (an illustration)', '“我们是领先的、一流的端到端协同解决方案提供商。”（举例）'), cat='clear', why=T('Nobody can say what it means. Question 2: is it easy to understand?', '没人说得清它是什么意思。第 2 问：好懂吗？')),
        dict(text=T('“We offer our staff the best working lives in the sector.” (an illustration)', '“我们给员工业内最好的工作生活。”（举例）'), cat='cust', why=T('It is about the firm, not the customer. Question 1.', '说的是企业，不是顾客。第 1 问。')),
        dict(text=T('“The cheapest and the finest in the whole country, guaranteed.” (an illustration)', '“全国最便宜，也是最好的，保证。”（举例）'), cat='honest', why=T('Cheapest and finest pull in opposite directions. Question 6: is it honest?', '最便宜和最好是互相拉扯的。第 6 问：诚实吗？')),
        dict(text=T('A promise of same-day delivery in a business with no delivery capability (an illustration)', '在一个没有配送能力的业务里承诺当日送达（举例）'), cat='fit', why=T('The promise cannot be kept with what the firm has. Question 4: is it strategically compatible?', '凭企业现有的东西无法兑现。第 4 问：与战略相容吗？')),
        dict(text=T('A promise of friendly personal service in a firm that pays staff only per transaction (an illustration)', '在只按交易笔数给员工付钱的企业里，承诺亲切的个人服务（举例）'), cat='cult', why=T('The culture would break it. Question 5: is it acceptable given our culture?', '企业文化会把它搞砸。第 5 问：在我们的文化里可接受吗？')),
    ]
    return dict(
        id=f'{CID}-value-proposition',
        title=T('Can you say what you promise in one sentence?', '你能用一句话说出你的承诺吗？'),
        description=T('Build a value proposition sentence for Who Gives a Crap, then critique propositions that fail, and keep it apart from a slogan.', '为 Who Gives a Crap 搭一句价值主张，再批评那些不合格的主张，并把它和口号区分开。'),
        minutes=35,
        skills=[{'id': SK, 'name': T('Explaining, writing and critiquing a value proposition', '解释、撰写并批评价值主张')}],
        misconceptions=[
            {'id': 'vp-is-slogan', 'description': T('a value proposition is the company slogan', '价值主张就是公司的口号')},
            {'id': 'vp-lists-features', 'description': T('a value proposition lists the product’s features', '价值主张就是罗列产品功能')},
        ],
        steps=[
            read('puzzle', T('A slogan is not a promise', '口号不是承诺'),
                 p(T("Coles states its purpose as “Helping Australians eat and live better every day.” It is a fine line to put on a wall. But ask a shopper at the self-checkout what they are being promised, and they cannot tell you. A **value proposition** is the opposite of a motto: it is a **promise of value** the customer believes will be delivered and experienced.",
                     "Coles 把自己的宗旨表述为“帮助澳大利亚人每天吃得更好、过得更好”。挂在墙上很好。但你问自助结账旁的购物者：这家店向我承诺了什么？他说不出来。**价值主张**恰恰和口号相反：它是顾客相信会被兑现并体验到的**价值承诺**。")),
                 chapter=CH['puzzle']),
            predict('guess', SK, T("Which is a value proposition, not a slogan?", "下面哪一句是价值主张，而不是口号？"),
                    [(T("“For painting contractors who need lower labour costs, our paint dries so fast that two coats fit in a day, unlike traditional paints.”", "“对想降低人工成本的涂装承包商，我们的漆干得极快，一天能刷两遍，不像传统油漆。”"), True),
                     (T("“Paint with passion.”", "“涂出激情。”"), T("A slogan: there is no customer, no problem, no alternative, no promise.", "是口号：没有顾客、没有问题、没有对比、没有承诺。")),
                     (T("“The world’s best paint company.”", "“全球最好的涂料公司。”"), T("A claim about the firm, with no customer in it.", "是关于企业的断言，里面没有顾客。")),
                     (T("“Quality, integrity, innovation.”", "“品质、诚信、创新。”"), T("Values of the company, not a promise to a customer.", "是公司的价值观，不是对顾客的承诺。"))],
                    T("The winner names **who**, **the problem**, **what we offer**, **the benefit**, **versus whom** and **the one difference**. That is the six-part sentence you will now build.", "对的那句有**谁**、**什么问题**、**我们提供什么**、**什么利益**、**比谁强**、**唯一区别**。这就是你现在要搭的六段式句子。")),
            read('touch', T('Build the sentence', '搭出这句话'),
                 p(T("Six pieces of a value proposition for Who Gives a Crap. This is the course’s reading of the company from its own public claims, not a statement it has published.", "Who Gives a Crap 价值主张的六个片段。这是本课程根据公司公开说法做出的解读，不是公司发布的陈述。")),
                 place(T('Six pieces to place into the slots of the sentence: for, who need, our business, that provides, unlike, this offering.', '六个片段，放进句子的各个位置：For、who need、our business、that provides、unlike、this offering。'), zones, chips, cols=2,
                       done=T("Read it as one sentence: **For** households that want purchases to reflect their values, **who need** a toilet paper that does good without extra effort, **our business** sells recycled and bamboo paper delivered direct, **that provides** a purchase that funds water and sanitation (50% of profits), **unlike** supermarket and branded paper, **this offering** has the giving built in and certified.", "连起来读：**For** 希望购买体现价值观的家庭，**who need** 一种不费劲就能做好事的卷纸，**our business** 卖直送的再生纸和竹子卷纸，**that provides** 一次资助供水和卫生的购买（50% 利润），**unlike** 超市和品牌卷纸，**this offering** 把捐赠内置并经过认证。"), height=920),
                 chapter=CH['touch']),
            read('touch2', T('The critic', '挑刺的人'),
                 p(T("A proposition can be well built and still be a poor one. Each of these fails one of the critique questions. Say which. The five here are made-up illustrations.", "一句价值主张结构完整，仍可能不好。下面每一句都没通过某一个检验问题。说出是哪个。这五句是为说明而编的。")),
                 tag(T('Five weak propositions to tag with the critique question each one fails.', '五句不好的价值主张，标出各自没通过的检验问题。'), cats, items,
                     done=T("Seven questions in all: **customer’s view? easy to understand? does it capture the value you offer (people, channel, partners)? strategically compatible? acceptable in our culture? honest? promotable?** Run them on any proposition you write.", "一共七问：**是顾客视角吗？好懂吗？涵盖了你提供的价值（人、渠道、伙伴）吗？与战略相容吗？在我们的文化里可接受吗？诚实吗？能被推广吗？**写完任何一句价值主张都用它们过一遍。"), height=640)),
            read('name', T('The framework, as the marker wants it', '阅卷人要的框架'),
                 p(T("A **value proposition** is a promise of value to be delivered, and a belief from the customer that the value will be experienced. It is **not the corporate slogan**. The six-part statement:", "**价值主张**是将要交付的价值承诺，以及顾客相信这份价值会被体验到。它**不是公司口号**。六段式陈述：")),
                 table([T('Slot', '位置'), T('Say', '写什么')],
                       [T('For', 'For'), T('the target customer (a different proposition for each segment)', '目标顾客（每个细分一套不同的主张）')],
                       [T('Who need', 'Who need'), T('the critical problem or opportunity', '关键问题或机会')],
                       [T('Our business', 'Our business'), T('what we offer, in a category everyone understands', '我们提供什么，放进大家都懂的类别')],
                       [T('That provides', 'That provides'), T('benefits, not features; pick the one most compelling, quantified if possible', '写利益而不是功能；选最有说服力的一条，能量化就量化')],
                       [T('Unlike', 'Unlike'), T('the main competitors and alternatives', '主要竞争对手和替代方案')],
                       [T('This offering', 'This offering'), T('the single most important difference', '最重要的那一个区别')]),
                 p(T("A B2B example: for painting contractors who need to cut the cost of labour (paint is only 15% of their costs), a fast-drying paint that lets two coats go on in a day, unlike traditional paint makers, reduces the labour cost. Note the benefit is about **their** cost, not about paint.", "一个 B2B 例子：对想降低人工成本的涂装承包商（油漆只占其成本的 15%），一种快干漆让一天能刷两遍，不像传统油漆厂商，从而降低人工成本。注意利益讲的是**他们的**成本，不是油漆。")),
                 h(T('Six properties of a good one, and seven questions to check it', '好主张的六个特性，和检查它的七个问题')),
                 ul(T("**Focused** on critical customer benefits", "**聚焦**关键的顾客利益"), T("**Significantly superior** to alternatives", "**明显优于**替代方案"), T("**Sustainable**, often resting on intangibles", "**可持续**，往往依靠无形资产"),
                    T("**Unanticipated**: it changes the rules", "**出人意料**：改变规则"), T("**Transferable**: the learning travels to other markets", "**可迁移**：学到的东西能用到别的市场"), T("**Deliverable**: the firm has the capability", "**可交付**：企业有这个能力")),
                 chapter=CH['name']),
            apply_q('apply', SK, T("Write a value proposition for **Hilton Honors members** in the six-part form (one line per slot, short). Use true facts: members can use a points-and-money slider, get an exclusive member discount and free standard Wi-Fi when they book through Hilton’s channels.", "用六段式为 **Hilton Honors 会员**写一句价值主张（每段一行，简短）。用真实事实：会员通过 Hilton 渠道预订时，可用积分加现金滑块，享会员专属折扣和免费标准 Wi-Fi。"),
                    [T("Targets a specific customer (frequent travellers who book direct)", "指向具体顾客（经常出行、直接预订的人）"), T("States a customer problem (cost and hassle of booking and staying)", "说出顾客的问题（预订和住宿的成本与麻烦）"),
                     T("Benefits, not features, with the real Honors benefits", "写利益而不是功能，用真实的 Honors 福利"), T("Names alternatives (booking through third-party sites) and one difference", "点出替代方案（通过第三方网站预订）和一个区别")],
                    T("For frequent travellers who book direct, who need to cut the cost and hassle of booking and staying, Hilton Honors provides a points-and-money option, a member-only discount and free standard Wi-Fi, unlike booking through a third-party site, because members get benefits only when they book through Hilton’s own channels.",
                      "对经常出行、直接预订的旅客，他们需要降低预订和住宿的成本与麻烦，Hilton Honors 提供积分加现金选项、会员专属折扣和免费标准 Wi-Fi，不同于通过第三方网站预订，因为会员只有通过 Hilton 自己的渠道预订才能享受这些福利。"),
                    T("One sentence, one customer, one difference.", "一句话，一个顾客，一个区别。")),
            choice('neighbour', T('The look-alike', '长得像的那个'), SK,
                   T("“Helping Australians eat and live better every day.” By the critique questions, what is the main weakness as a value proposition?", "“帮助澳大利亚人每天吃得更好、过得更好。”按检验问题，作为价值主张，主要弱点是什么？"),
                   [(T("It names no segment, problem or alternative, so it is a purpose statement, not a proposition", "没有细分、问题或替代方案，所以是宗旨陈述，不是价值主张"), True),
                    (T("It is dishonest", "不诚实"), T("Nothing says it is dishonest; it is vague.", "没有任何迹象说它不诚实；它只是笼统。")),
                    (T("It is too long", "太长"), T("Length is not the problem.", "长度不是问题。"))],
                   T("Purpose and value proposition are different things.", "宗旨和价值主张是两回事。"), purpose='check', chapter=CH['neighbour']),
            recall('r1', SK, T("From lesson 5: what gives a value proposition its “for”?", "来自第 5 课：价值主张的“For”从哪来？"),
                   [(T("The target segment chosen in segmentation and targeting", "细分与目标市场选择里选出的目标细分"), True), (T("The product features", "产品功能"), T("Features belong in “our business”.", "功能写在“our business”里。"))], T("Different segments get different propositions.", "不同细分有不同的主张。"), first=True),
            recall('r2', SK, T("From lesson 4: a proposition is “sustainable” when it rests on…", "来自第 4 课：主张“可持续”是因为它依靠……"),
                   [(T("something hard to copy, such as a core competence or intangibles", "难以模仿的东西，如核心能力或无形资产"), True), (T("a temporary price cut", "临时降价"), T("Easiest thing to copy.", "最容易被模仿。"))], T("VRIN again.", "又是 VRIN。")),
        ] + exam_three('exam', SK,
                       T("Question. (a) Explain what a value proposition is and how it differs from a slogan. (b) Apply the idea to Coles in Australia. (c) Make two recommendations.", "题目。(a) 解释什么是价值主张，以及它与口号的区别。(b) 把它应用到澳大利亚的 Coles。(c) 给出两条建议。"),
                       (T("Write the **Explain** part.", "写**解释**部分。"),
                        [T("A promise of value to a target customer, which the customer believes will be experienced", "对目标顾客的价值承诺，顾客相信会体验到"), T("Not a slogan: it names a segment, problem, benefit, alternative and difference", "不是口号：有细分、问题、利益、替代方案、区别"),
                         T("The six-part statement (for, who need, our business, that provides, unlike, this offering)", "六段式陈述"), T("Properties: focused, superior, sustainable, unanticipated, transferable, deliverable", "特性：聚焦、更优、可持续、出人意料、可迁移、可交付")],
                        T("A value proposition is a promise of value to a specific customer segment, together with the customer’s belief that the value will be delivered and experienced. It differs from a slogan, which is a message about the firm, because it states the customer, the problem, the benefit, the alternatives and the single difference: for, who need, our business, that provides, unlike, this offering. A good one is focused, significantly superior, sustainable, unanticipated, transferable and deliverable, and can be tested with questions such as whether it takes the customer’s perspective and is honest.",
                          "价值主张是对特定顾客细分的价值承诺，加上顾客相信这份价值会被交付并体验到。它不同于口号，口号是关于企业的信息，而价值主张写明顾客、问题、利益、替代方案和唯一区别：for、who need、our business、that provides、unlike、this offering。好的主张聚焦、明显更优、可持续、出人意料、可迁移、可交付，并能用“是否站在顾客视角、是否诚实”等问题检验。")),
                       (T("Write the **Apply** part.", "写**应用**部分。"),
                        [T("Writes a value proposition for a named Coles segment", "为一个明确的 Coles 细分写出价值主张"), T("Uses true Coles facts (same-day delivery from fulfilment centres, online sales up 26.4%, Own Brand with 100% Australian-grown fresh meat, milk and eggs, Flybuys, cost savings funding value)", "用真实的 Coles 事实"),
                         T("Contrasts with its stated purpose as a slogan-like statement", "把它与自己宣称的宗旨（类似口号）对比"), T("Critiques it with at least two of the seven questions, with reasons", "用七问中至少两问批评它，并给理由")],
                        T("For time-poor households who need a full shop without a trip, Coles’ online business provides same-day delivery from its own fulfilment centres, unlike a trip to a store, because Coles has built that capability: online sales rose 26.4% to 13.6% of supermarket sales in FY26. For the other main segment, value-seeking families, Own Brand ranges, whose fresh meat, milk and eggs are 100% Australian-grown, provide trusted quality while cost savings are reinvested in value. Coles’ stated purpose, helping Australians eat and live better every day, is not a proposition, because it names no segment or alternative. Tested against the questions, the delivery proposition is deliverable and honest because the capability exists; its risk is acceptability for stores whose teams must pick orders, which shows why deliverability is checked against culture.",
                          "对没时间、需要不用跑店就能买齐一周所需的家庭，Coles 的线上业务用自有履约中心提供当日送达，不同于跑一趟门店，因为 Coles 已建好这项能力：2026 财年线上销售增长 26.4%，占超市销售 13.6%。对另一个主要细分——看重性价比的家庭——自有品牌系列（其鲜肉、牛奶和鸡蛋 100% 为澳大利亚产）提供可信的品质，同时把成本节省再投入价格。Coles 宣称的宗旨“帮助澳大利亚人每天吃得更好、过得更好”不是价值主张，因为没有点出细分或替代方案。用检验问题衡量，配送主张可交付且诚实，因为能力真实存在；它的风险是门店团队要拣货，这说明可交付性也要结合文化来检验。")),
                       (T("Write the **Recommend** part: exactly two.", "写**建议**部分：恰好两条。"),
                        [T("Exactly two from the analysis (write segment-specific propositions; fix the purpose statement by making the promise measurable)", "恰好两条，从分析里推出（写面向细分的主张；让宗旨里的承诺可衡量）"), T("Each actionable", "每条可执行"), T("Names a risk", "点出风险")],
                        T("First, publish a distinct promise for each main segment, such as a time-saving delivery promise for busy households and a value promise for families, because one purpose statement cannot be tested by anyone. The risk is inconsistency across messages, so one team owns the wording. Second, attach one measurable commitment to the delivery promise, such as a delivery window, so the promise is deliverable and honest. The risk is failing the window at peak times, so set it only for areas the fulfilment centres can serve.",
                          "第一，为每个主要细分发布不同的承诺，比如对忙碌家庭的“省时送达”承诺和对家庭的“性价比”承诺，因为一句宗旨没人能检验。风险是各信息之间不一致，所以由一个团队负责措辞。第二，给配送承诺加一个可衡量的约定，如送达时段，让承诺可交付、可兑现。风险是高峰期做不到，所以只在履约中心能覆盖的地区设定。")),
                       ),
    )
